def transform(grid):
    h,w=len(grid),len(grid[0])
    bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
    out=[[bg]*w for _ in range(h)]
    seen=set()
    for r in range(h):
        for c in range(w):
            if grid[r][c]==bg or (r,c) in seen: continue
            color=grid[r][c]; cells=[]; stack=[(r,c)]; seen.add((r,c))
            while stack:
                a,b=stack.pop(); cells.append((a,b))
                for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                    na,nb=a+da,b+db
                    if 0<=na<h and 0<=nb<w and grid[na][nb]==color and (na,nb) not in seen:
                        seen.add((na,nb)); stack.append((na,nb))
            minr=min(a for a,b in cells); maxr=max(a for a,b in cells)
            dr=-minr if color%2 else h-1-maxr
            for a,b in cells: out[a+dr][b]=color
    return out

